// The document is a UsdStage: everything shown in the view is a part of it, made of features and
// regenerated by the kernel. No geometry lives in code.
//
//   /<Root>                Xform   aiad:parameters (JSON list), aiad:materials (JSON object)
//   /<Root>/Looks/<M>      Material (UsdPreviewSurface), one per material of the table
//   /<Root>/<Body>         Xform   aiad:body = "<Body>" (a rigid body; the simulation poses it)
//   /<Root>/<Body>/<Part>  Xform   aiad:name, aiad:material, aiad:role, aiad:sectioned (cut by the section view), aiad:features (JSON), aiad:error
//        Shape             BrepArray, the exact geometry of the part (written by regeneration)
//   /<Root>/Joints/<J>     UsdPhysics*Joint between two bodies; aiad:name, aiad:type, aiad:point, aiad:axis
//                          (formulas, the definition), aiad:motor, aiad:limits; the physics attributes follow them
//   /<Root>/Elements/<E>   Scope   aiad:name, aiad:type, aiad:definition (JSON): what else the machine is made of
//                          (gears, belts, cams, springs, loads, chambers, magnetos), tied to joints and parts
#pragma once

#include "Expression.h"
#include "Instruments.h"
#include "Json.h"
#include "Kernel.h"

#include <pxr/usd/sdf/layer.h>
#include <pxr/usd/usd/stage.h>

#include <array>
#include <functional>
#include <map>
#include <memory>
#include <optional>
#include <set>
#include <string>
#include <vector>

namespace aiad::doc
{

struct Parameter
{
    std::string name;
    Json value;                      // number or formula (string)
    std::string unit, description;
    std::optional<double> minimum, maximum;
};

struct Material
{
    std::string name;
    double density = 1000.0;         // [kg/m^3]
    std::array<double, 3> colour{0.7, 0.7, 0.7};
    double metallic = 0.0, roughness = 0.5, emission = 0.0;
    // Physics beyond the mass (0 = not given): coil springs need the shear modulus, spiral springs the elastic
    // (Young's) modulus, magnets the remanence, magnetic circuits the relative permeability.
    double shearModulus = 0.0;           // [Pa]
    double elasticModulus = 0.0;         // [Pa]
    double remanence = 0.0;              // [T]
    double relativePermeability = 0.0;
};

// A joint of the mechanism: how two bodies may move relative to each other. The simulation is built from
// the joints of the document (no machine is known to the code).
struct JointInfo
{
    std::string name;
    std::string type;                // revolute | prismatic | cylindrical | spherical | planar | fixed
    std::string body0, body1;        // body1 empty = the ground (the world)
    Json point = Json::array({0, 0, 0});   // model frame [m]: numbers or formulas
    Json axis = Json::array({0, 0, 1});    // rotation / sliding axis (or plane normal for planar)
    Json motor;                      // null, or {"mode": "speed" | "torque", "value": number | formula}
                                     //   speed: rad/s (rotation) or m/s (sliding); torque: N m or N;
                                     //   torque only: "free_speed" (DC-motor curve), "duration" [s]
    Json limits;                     // null, or [lower, upper]: stops of the coordinate (rad or m), each a
                                     //   number, formula or null (no stop on that side)
    Json start;                      // null, or where the coordinate starts instead of the drawn position: a number or
                                     //   formula (rad or m), or {"local_time": period [s], "offset": rad} (rotation): from
                                     //   the computer's local date and time when the simulation starts (a watch's hands)
};

// An element of the machine besides bodies and joints, tied to them and to the drawn parts:
//   gear {joint0, joint1, part0, part1, internal}      the teeth of the drawn gears couple two joints
//   belt {joint0, joint1, part0, part1, belt}          a belt or chain around two drawn wheels
//   rack {joint0 (pinion), joint1 (slide), part0}      a drawn pinion drives a sliding rack
//   contact {part, body, point, normal, radius}        a drawn profile (cam, rocker pad) pushes a flat face
//   spring {part, body0, point0, body1, point1, free_length}   a drawn coil spring between two bodies
//   load {joint, constant, linear, quadratic}          resisting torque / force (friction, brake, propeller)
//   chamber {piston, cylinder, head, intake, exhaust, ignition}   a gas chamber closed by a piston (0D cycle)
//   magneto {rotor, magnet, shoes, core, coil, points_open}       a flywheel magneto firing a chamber
struct ElementInfo
{
    std::string name, type;
    Json definition = Json::object();
};

struct PartInfo
{
    pxr::SdfPath path;
    std::string name, body, material, role;
    bool sectioned = false;
    Json features = Json::array();
    std::string error;               // last regeneration error (empty = ok)
};

struct ParameterSolver;

class Document
{
public:
    // A new empty document (in memory until saved).
    static std::unique_ptr<Document> Create(const std::string& rootName);
    // Opens a saved document; the exact geometry is read back from its BrepArray prims.
    static std::unique_ptr<Document> Open(const std::string& path, std::string& error);
    bool Save(const std::string& path, std::string& error);
    const std::string& Path() const { return m_path; }

    const pxr::UsdStageRefPtr& Stage() const { return m_stage; }
    pxr::SdfPath Root() const { return m_root; }
    uint64_t Revision() const { return m_revision; }

    // ---- Parameters (formulas allowed; cycles and unknown names are errors) ----
    std::vector<Parameter> Parameters() const;
    std::optional<Parameter> FindParameter(const std::string& name) const;
    bool Value(const std::string& name, double& value, std::string& error) const;
    double Value(const std::string& name) const;  // 0 when missing or invalid
    NameLookup Lookup() const;
    // Defines or replaces one parameter; regenerates the parts that depend on it.
    bool DefineParameter(const Parameter& parameter, std::string& error);
    // Sets several values at once (name -> number or formula); regenerates dependents; atomic.
    bool SetParameters(const Json& values, std::string& error, std::vector<std::string>* regenerated = nullptr);
    bool RemoveParameter(const std::string& name, std::string& error);

    // ---- Materials ----
    std::vector<Material> Materials() const;
    std::optional<Material> FindMaterial(const std::string& name) const;
    bool DefineMaterial(const Material& material, std::string& error);

    // ---- Bodies and parts ----
    std::vector<std::string> Bodies() const;
    // Rest placement of a body (formulas): its origin in the model frame. The simulation moves bodies
    // relative to it.
    // fixed: the body is part of the ground (it does not move); unset keeps the current value.
    bool DefineBody(const std::string& body, const Json& origin, std::string& error, std::optional<bool> fixed = std::nullopt);
    bool BodyFixed(const std::string& body) const;
    kernel::Vec3 BodyOrigin(const std::string& body) const;
    Json BodyOriginDefinition(const std::string& body) const;
    // Orientation of the whole model in the world (rotation about an axis through the origin).
    bool SetOrientation(const kernel::Vec3& axis, double angleDeg, std::string& error);
    pxr::SdfPath BodyPath(const std::string& body) const;
    std::vector<PartInfo> Parts() const;
    // By path ("/Engine/Piston/Piston"), exact name, or unique case-insensitive name fragment.
    std::optional<PartInfo> FindPart(const std::string& reference, std::string& error) const;
    // Creates the part (and its body if new) and regenerates it. A regeneration failure is an error
    // and nothing is created.
    bool CreatePart(PartInfo part, std::string& error);
    // Replaces the part's definition (features, material, role, sectioned, name; body moves the prim).
    bool UpdatePart(const pxr::SdfPath& path, const PartInfo& part, std::string& error);
    bool DeletePart(const pxr::SdfPath& path, std::string& error);
    // Exact state of a part for undo (definition + geometry); RestorePart(path, null) deletes.
    Json Snapshot(const pxr::SdfPath& path) const;
    bool Restore(const pxr::SdfPath& path, const Json& snapshot, std::string& error);

    // ---- Joints ----
    std::vector<JointInfo> Joints() const;
    std::optional<JointInfo> FindJoint(const std::string& name) const;
    // Creates or replaces a joint (checked: type, bodies, point and axis evaluate, motor).
    bool DefineJoint(const JointInfo& joint, std::string& error);
    bool DeleteJoint(const std::string& name, std::string& error);
    // [x, y, z] of numbers or formulas, evaluated with the parameters.
    bool EvaluateVector(const Json& vector, kernel::Vec3& out, std::string& error) const;
    // A number or a formula.
    bool EvaluateNumber(const Json& value, double& out, std::string& error) const;

    // ---- Elements ----
    std::vector<ElementInfo> Elements() const;
    std::optional<ElementInfo> FindElement(const std::string& name) const;
    // Creates or replaces an element (checked: type, fields, the joints, parts, bodies and elements it names,
    // its formulas).
    bool DefineElement(const ElementInfo& element, std::string& error);
    bool DeleteElement(const std::string& name, std::string& error);

    // ---- Geometry ----
    // The exact solid of a part and what is derived from it (display mesh, mass properties), cached until
    // the part's solid is rebuilt; ShapeRevision changes every time it is (0: no solid).
    const kernel::Solid* Shape(const pxr::SdfPath& part) const;
    uint64_t ShapeRevision(const pxr::SdfPath& part) const;
    const kernel::Mesh* DisplayMesh(const pxr::SdfPath& part) const;   // 0.05 mm chord, 8 deg
    // The outline of a part on a plane (part frame): closed loops, the material on the left of each seen from
    // `normal`. Measured on a fine tessellation (chord 1/5000 of the part's size, at least 1 um): profiles that
    // touch (an escapement) are read from any solid, drawn or imported.
    std::vector<std::vector<kernel::Vec3>> SectionOutline(const pxr::SdfPath& part, const kernel::Vec3& point, const kernel::Vec3& normal) const;
    bool Bounds(const pxr::SdfPath& part, kernel::Vec3& minimum, kernel::Vec3& maximum) const;   // part frame
    // Volume of the part beyond the plane through `point` (part frame) on the side `normal` points to (exact cut).
    double VolumeBeyond(const pxr::SdfPath& part, const kernel::Vec3& point, const kernel::Vec3& normal) const;
    bool Mass(const pxr::SdfPath& part, kernel::MassProperties& out, std::string& error) const;
   bool Regenerate(const pxr::SdfPath& part, std::string& error);
    // Every part; returns the failures (part name -> message).
    std::map<std::string, std::string> RegenerateAll();

    // Called after every successful change (scene refresh, simulation rebuild).
    std::function<void()> OnChanged;
    // Measuring instruments (Instruments.h): they observe the machine and are not part of it, so changing one calls
    // OnInstrumentsChanged instead of OnChanged (the machine study stays as it is).
    std::vector<InstrumentInfo> Instruments() const;
    std::optional<InstrumentInfo> FindInstrument(const std::string& name) const;
    bool DefineInstrument(const InstrumentInfo& instrument, std::string& error);
    bool DeleteInstrument(const std::string& name, std::string& error);
    std::function<void()> OnInstrumentsChanged;
    // Called before the document is written (by the user or the agent): the app stores its view in it then.
    std::function<void()> OnSaving;
    // The last view of the document (camera, as the app writes it; JSON, empty when never saved): kept with the
    // document but not a change of the drawing (no undo, no unsaved-changes mark).
    std::string View() const;
    void SetView(const std::string& view);

private:
    Document() = default;
    PartInfo ReadPart(const pxr::UsdPrim& prim) const;
    void WritePart(pxr::UsdPrim& prim, const PartInfo& part);
    bool BuildGeometry(const pxr::SdfPath& path, const PartInfo& part, std::string& error);
    bool WriteShape(const pxr::SdfPath& path, const std::string& material, const kernel::Solid& solid, std::string& error);
    void WriteMaterialPrims();
    void WriteParameters(const std::vector<Parameter>& parameters);
    void Changed();
    void WriteJointPhysics(pxr::UsdPrim& prim, const JointInfo& joint);
    pxr::SdfPath JointPath(const std::string& name) const;
    pxr::SdfPath ElementPath(const std::string& name) const;
    std::vector<pxr::SdfPath> Dependents(const std::set<std::string>& names) const;

    pxr::UsdStageRefPtr m_stage;
    pxr::SdfPath m_root;
    std::string m_path;
    struct ShapeEntry
    {
        kernel::Solid solid;
        uint64_t revision = 0;
        mutable std::shared_ptr<kernel::Mesh> mesh, fineMesh;
        mutable std::optional<kernel::MassProperties> unitMass;   // density 1 (scaled by the material's)
        mutable std::optional<std::pair<kernel::Vec3, kernel::Vec3>> bounds;
        mutable std::map<std::array<double, 6>, double> cuts;
        uint64_t key = 0;   // fingerprint of the stored solid: the derived values saved with it are its own
    };
    void SetShape(const pxr::SdfPath& path, kernel::Solid solid);
    // Mass and bounds are kept with the part in the file (attribute aiad:derived, with the fingerprint of its solid):
    // the exact mass of an imported part costs seconds (SMLib rebuilds its trim curves every time).
    void LoadDerived(const pxr::SdfPath& part);
    void StoreDerived(const pxr::SdfPath& part) const;
    std::map<pxr::SdfPath, ShapeEntry> m_shapes;
    pxr::SdfLayerRefPtr m_carry;   // a moved or renamed part's stored geometry, while it is recreated (UpdatePart)
    pxr::SdfPath m_carryFrom;
    uint64_t m_shapeCounter = 0;
    uint64_t m_revision = 0;
    // Parameters parsed and evaluated once per change of the parameter table (the panels and the study
    // read them thousands of times).
    uint64_t m_parameterRevision = 1;
    mutable uint64_t m_cachedParameters = 0;
    mutable std::vector<Parameter> m_parameterList;
    mutable std::shared_ptr<ParameterSolver> m_solver;
    void CacheParameters() const;
    uint64_t m_materialRevision = 1;
    mutable uint64_t m_cachedMaterials = 0;
    mutable std::vector<Material> m_materialList;
};

// Valid prim name from a display name ("Crank web (magneto side)" -> "Crank_web_magneto_side").
std::string PrimName(const std::string& display);

}  // namespace aiad::doc
